int main() {
    auto toString = [](int i) {
        return fmt::format(FMT_STRING("string-{:03}"), i);
    };
    auto strings = numbers
                 | ranges::views::transform(toString)
                 | ranges::to_vector;


    // Fails: the result contains empty strings
    ranges::stable_sort(strings);

    // Works as expected
    //std::stable_sort(strings.begin(), strings.end());
    //ranges::sort(strings);
    //std::sort(strings.begin(), strings.end());

    for (auto&& [i, s] : ranges::views::enumerate(strings)) {
        std::cout << "item " << std::setw(3) << i << ": '" << s << "'\n";
    }
}
